with issues as(select 'curso sem módulos' issue,c.id::text reference from public.courses c where c.status='published' and not exists(select 1 from public.course_modules m where m.course_id=c.id) union all select 'módulo sem aulas',m.id::text from public.course_modules m join public.courses c on c.id=m.course_id where c.status='published' and not exists(select 1 from public.lessons l where l.module_id=m.id and l.status='published') union all select 'aula sem vídeo',l.id::text from public.lessons l where l.status='published' and not exists(select 1 from public.lesson_videos v where v.lesson_id=l.id and v.youtube_id~'^[A-Za-z0-9_-]{11}$') union all select 'posição de módulo duplicada',course_id::text||':'||position from public.course_modules group by course_id,position having count(*)>1 union all select 'posição de aula duplicada',module_id::text||':'||position from public.lessons group by module_id,position having count(*)>1) select * from issues order by issue,reference;
